// Night-prayer content generated by scripts/convert-night-prayer.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

export type QuranVerse = { surah: number; ayah: number; text: string };

/** A sourced item: a hadith/dua (`text`) or a Quran passage (`verses`). */
export type QiyamItem = {
  title: string;
  text?: string;
  verses?: QuranVerse[];
  refAr?: string;
  refEn?: string;
  source?: string;
  note?: string;
  repeat?: number;
};

export type NightPrayerContent = {
  virtues: QiyamItem[];
  howTo: QiyamItem[];
  duas: QiyamItem[];
  helps: string[];
};

export const getNightPrayerContent = cache(
  async (): Promise<NightPrayerContent> =>
    JSON.parse(await fs.readFile(path.join(process.cwd(), "data/night-prayer/content.json"), "utf8")),
);
